diff --git a/crates/ocean-surface-ui/src/components.rs b/crates/ocean-surface-ui/src/components.rs
index 3376b81..c422756 100644
--- a/crates/ocean-surface-ui/src/components.rs
+++ b/crates/ocean-surface-ui/src/components.rs
@@ -11,6 +11,9 @@ use wasm_bindgen::prelude::*;

 use crate::daemon::{Daemon, PinnedWidget};

+mod interactive_plot;
+use interactive_plot::InteractivePlotView;
+
 #[wasm_bindgen]
 extern "C" {
     /// Defined in index.html. Loads the Google Maps JS API + Places UI Kit
@@ -71,6 +74,10 @@ pub fn ComponentView(
             <ChartView kind_props />
         }
         .into_any(),
+        "interactive_plot" => view! {
+            <InteractivePlotView component_id kind_props daemon />
+        }
+        .into_any(),
         "timeline" => view! {
             <TimelineView kind_props />
         }
diff --git a/styles/components.css b/styles/components.css
index 3b7512c..12bf7cc 100644
--- a/styles/components.css
+++ b/styles/components.css
@@ -9,6 +9,7 @@
 .component-markdown,
 .component-dashboard,
 .component-chart,
+.component-interactive-plot,
 .component-timeline,
 .component-stats,
 .component-filetree,
@@ -29,6 +30,7 @@
 .component-markdown,
 .component-dashboard,
 .component-chart,
+.component-interactive-plot,
 .component-timeline,
 .component-stats,
 .component-filetree,
@@ -52,6 +54,7 @@
 .data-table th,
 .progress-label,
 .component-chart__title,
+.interactive-plot__title,
 .diff__filename,
 .code__lang,
 .stat-card__label,
@@ -764,6 +767,261 @@ select.form-field__input {
   to { transform: scaleX(1); }
 }

+/* ---- Interactive plot ------------------------------------------------- */
+.component-interactive-plot {
+  display: grid;
+  gap: 14px;
+}
+
+.component-interactive-plot--error {
+  gap: 4px;
+  color: var(--fg-2);
+  font-size: 13px;
+}
+
+.component-interactive-plot--error strong {
+  color: var(--fg);
+}
+
+.interactive-plot__title {
+  margin: 0;
+}
+
+.interactive-plot__description {
+  max-width: 72ch;
+  margin: -8px 0 0;
+  color: var(--fg-2);
+  font-size: 13px;
+  line-height: 1.5;
+}
+
+.interactive-plot__graph {
+  min-width: 0;
+  padding: 12px;
+  background: var(--bg-well);
+  box-shadow: var(--well);
+  border-radius: var(--radius);
+}
+
+.interactive-plot__plot-area {
+  position: relative;
+  min-width: 0;
+  padding: 12px 0 14px 42px;
+}
+
+.interactive-plot__plot-area svg {
+  display: block;
+  width: 100%;
+  height: clamp(170px, 32vw, 260px);
+  overflow: visible;
+}
+
+.interactive-plot__grid {
+  stroke: var(--border);
+  stroke-width: 0.5;
+  vector-effect: non-scaling-stroke;
+}
+
+.interactive-plot__line {
+  fill: none;
+  stroke: var(--accent);
+  stroke-width: 2;
+  stroke-linecap: round;
+  stroke-linejoin: round;
+  vector-effect: non-scaling-stroke;
+}
+
+.interactive-plot__line--2 { stroke: var(--info); }
+.interactive-plot__line--3 { stroke: var(--ok); }
+.interactive-plot__line--4 { stroke: var(--warn); }
+.interactive-plot__line--5 { stroke: var(--err); }
+.interactive-plot__line--6 { stroke: var(--accent-bright); }
+
+.interactive-plot__y-label,
+.interactive-plot__x-axis,
+.interactive-plot__y-max,
+.interactive-plot__y-min {
+  color: var(--fg-3);
+  font-family: var(--mono);
+  font-size: 10px;
+}
+
+.interactive-plot__y-label {
+  min-height: 14px;
+  padding-left: 42px;
+}
+
+.interactive-plot__y-max,
+.interactive-plot__y-min {
+  position: absolute;
+  left: 0;
+  width: 36px;
+  overflow: hidden;
+  text-align: right;
+  text-overflow: ellipsis;
+  white-space: nowrap;
+}
+
+.interactive-plot__y-max { top: 8px; }
+.interactive-plot__y-min { bottom: 10px; }
+
+.interactive-plot__x-axis {
+  display: grid;
+  grid-template-columns: 1fr auto 1fr;
+  gap: 8px;
+  padding-left: 42px;
+}
+
+.interactive-plot__x-axis span:last-child {
+  text-align: right;
+}
+
+.interactive-plot__error {
+  padding: 28px 12px;
+  color: var(--err);
+  font-size: 12px;
+  text-align: center;
+}
+
+.interactive-plot__metrics {
+  display: grid;
+  grid-template-columns: repeat(auto-fit, minmax(120px, 1fr));
+  gap: 8px;
+}
+
+.interactive-plot__metric {
+  display: grid;
+  gap: 4px;
+  min-width: 0;
+  padding: 10px 12px;
+  background: var(--bg-well);
+  box-shadow: var(--well);
+  border-radius: var(--radius);
+}
+
+.interactive-plot__metric span {
+  overflow: hidden;
+  color: var(--fg-3);
+  font-size: 11px;
+  text-overflow: ellipsis;
+  white-space: nowrap;
+}
+
+.interactive-plot__metric strong {
+  overflow: hidden;
+  color: var(--fg);
+  font-family: var(--mono);
+  font-size: 15px;
+  text-overflow: ellipsis;
+  white-space: nowrap;
+}
+
+.interactive-plot__controls {
+  display: grid;
+  grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
+  gap: 12px 16px;
+}
+
+.interactive-plot__control {
+  min-width: 0;
+  margin: 0;
+  padding: 0;
+  border: 0;
+}
+
+.interactive-plot__control legend {
+  width: 100%;
+  margin-bottom: 6px;
+  color: var(--fg-2);
+  font-size: 12px;
+}
+
+.interactive-plot__control-row {
+  display: grid;
+  grid-template-columns: minmax(100px, 1fr) auto;
+  align-items: center;
+  gap: 10px;
+}
+
+.interactive-plot__range {
+  width: 100%;
+  min-width: 0;
+  height: 28px;
+  margin: 0;
+  accent-color: var(--accent);
+  cursor: pointer;
+  touch-action: pan-y;
+}
+
+.interactive-plot__number-wrap {
+  display: flex;
+  align-items: center;
+  gap: 5px;
+  min-width: 86px;
+  padding: 5px 7px;
+  background: var(--bg-well);
+  box-shadow: var(--well);
+  border-radius: var(--radius-sm);
+}
+
+.interactive-plot__number {
+  width: 7ch;
+  min-width: 0;
+  padding: 0;
+  border: 0;
+  outline: 0;
+  background: transparent;
+  color: var(--fg);
+  font: 12px/1.4 var(--mono);
+  text-align: right;
+}
+
+.interactive-plot__number-wrap:focus-within {
+  box-shadow: var(--focus-ring), var(--well);
+}
+
+.interactive-plot__unit {
+  color: var(--fg-3);
+  font-family: var(--mono);
+  font-size: 10px;
+}
+
+.interactive-plot__sr-only {
+  position: absolute;
+  width: 1px;
+  height: 1px;
+  padding: 0;
+  margin: -1px;
+  overflow: hidden;
+  clip: rect(0, 0, 0, 0);
+  white-space: nowrap;
+  border: 0;
+}
+
+@media (max-width: 560px) {
+  .component-interactive-plot {
+    padding: 12px;
+  }
+
+  .interactive-plot__graph {
+    padding: 8px;
+  }
+
+  .interactive-plot__plot-area svg {
+    height: 170px;
+  }
+
+  .interactive-plot__controls {
+    grid-template-columns: minmax(0, 1fr);
+  }
+}
+
+@media (prefers-reduced-motion: reduce) {
+  .interactive-plot__line {
+    transition: none;
+  }
+}
+
 /* ---- Timeline ---------------------------------------------------------- */
 .component-timeline {
   padding: 16px;
diff --git a/crates/ocean-runtime/src/tools/component.rs b/crates/ocean-runtime/src/tools/component.rs
index a4a28f7..ea19d39 100644
--- a/crates/ocean-runtime/src/tools/component.rs
+++ b/crates/ocean-runtime/src/tools/component.rs
@@ -32,6 +32,7 @@ const VALID_KINDS: &[&str] = &[
     "markdown",
     "dashboard",
     "chart",
+    "interactive_plot",
     "timeline",
     "stat",
     "file_tree",
@@ -72,6 +73,7 @@ impl AgentTool for ComponentRenderTool {
          • Task/status board → 'kanban'. Collecting input → 'form' (then component_wait).\n\
          • A running task → 'progress'. A multi-step plan → 'timeline'.\n\
          • KPIs / metrics (views, plays, saves) → 'stat'. Numeric series to visualize → 'chart'.\n\
+         • A graph users should explore by changing numeric parameters → 'interactive_plot'.\n\
          • Project structure / file list → 'file_tree'. Showing code edits → 'diff'.\n\
          • A code snippet to copy → 'code'. An important note/warning → 'callout'.\n\
          • Images / screenshots / generated art → 'gallery'. A yes/no before something \
@@ -90,6 +92,7 @@ impl AgentTool for ComponentRenderTool {
          • markdown — { content: \"## md\" }. Rich prose; supports tables, bold, lists.\n\
          • dashboard — { children: [{ id, width, kind?, props? }] }. Grid; width is fr units; inline kind+props renders that component in the cell.\n\
          • chart — { title?, type: \"bar\"|\"line\", series: [{label, value}] }. value is numeric. Display only.\n\
+         • interactive_plot — { title?, description?, parameters: [{id,label?,min,max,step?,value,unit?}], plot: {x:{id?,label?,min,max,samples?}, y_label?, series:[{label,expression}]}, metrics?:[{label,expression,unit?,precision?}] }. Expressions use bounded arithmetic/functions; controls recompute locally and emit parameters_changed on commit.\n\
          • timeline — { steps: [{label, status: \"done\"|\"active\"|\"pending\"|\"error\", detail?}] }. Re-render with replace:true to advance.\n\
          • stat — { stats: [{label, value, delta?, trend: \"up\"|\"down\"|\"flat\"}] }. value is string or number.\n\
          • file_tree — { root?, entries: [{name, type: \"file\"|\"dir\", path?, children?}] }. Dirs nest via children. Files emit file_clicked { path }.\n\
@@ -121,7 +124,7 @@ impl AgentTool for ComponentRenderTool {
                     "type": "string",
                     "enum": [
                         "kanban", "form", "table", "progress", "markdown", "dashboard",
-                        "chart", "timeline", "stat", "file_tree", "diff", "code",
+                        "chart", "interactive_plot", "timeline", "stat", "file_tree", "diff", "code",
                         "callout", "gallery", "confirm", "map", "video"
                     ],
                     "description": "Component type. Defines the shape of `props`."
@@ -134,6 +137,7 @@ impl AgentTool for ComponentRenderTool {
                         progress: {label, value, max, indeterminate?}. markdown: {content}. \
                         dashboard: {children:[{id,width,kind?,props?}]}. \
                         chart: {title?, type:'bar'|'line', series:[{label,value}]}. \
+                        interactive_plot: {title?,description?,parameters:[{id,label?,min,max,step?,value,unit?}],plot:{x:{id?,label?,min,max,samples?},y_label?,series:[{label,expression}]},metrics?:[{label,expression,unit?,precision?}]}. \
                         timeline: {steps:[{label,status,detail?}]}. stat: {stats:[{label,value,delta?,trend?}]}. \
                         file_tree: {root?, entries:[{name,type,path?,children?}]}. \
                         diff: {filename?, lines:[{kind,text}]} or {filename?, unified:str}. \

